#include <SPI.h>
#include <Keypad.h>
#include <nRF24L01.h>
#include <RF24.h>
#include <LowPower.h>

// --- ПОДКЛЮЧЕНИЕ (актуальное) ---
#include <Crypto.h>
#include <AES.h>
#include <Low-Power.h>

// --- КРИПТОГРАФИЯ (Modern API) ---
//(Изменено) Шаблонный класс и пространство имен
Crypto::AES<128> aes; 
byte key[16] = { 
  0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
  0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F 
};

// --- ДАННЫЕ ---
byte transm_data[16]; 

// --- КЛАВИАТУРА ---
const byte ROWS = 4;
const byte COLS = 4;
char keys[ROWS][COLS] = {
  {'1', '2', '3', 'A'}, {'4', '5', '6', 'B'}, {'7', '8', '9', 'C'}, {'*', '0', '#', 'D'}
};
byte rowPins[ROWS] = {9, 8, 7, 6};
byte colPins[COLS] = {5, 4, 3, 2};
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

boolean armedFlag = false;
const int check = 111;
const byte crypt_key = 123;

void packTimestamp(byte* buffer, unsigned long value) {
    buffer[0] = (value >> 24) & 0xFF;
    buffer[1] = (value >> 16) & 0xFF;
    buffer[2] = (value >> 8) & 0xFF;
    buffer[3] = value & 0xFF;
}

void setup() {
  Serial.begin(9600);
  transm_data[0] = crypt_key;

  pinMode(15, OUTPUT); // redLED
  pinMode(17, OUTPUT); // greenLED
  digitalWrite(17, HIGH);
  digitalWrite(15, LOW);

  // --- НАСТРОЙКА РАДИО ---
  radio.begin();
  radio.setAutoAck(true);
  radio.setRetries(0, 15);
  radio.enableAckPayload();
  radio.setPayloadSize(16); 
  radio.setChannel(0x60);
  radio.setPALevel(RF24_PA_MAX);
  radio.powerUp();
  radio.stopListening();
  byte address[6] = {'1','N','o','d','e'}; 
  radio.openWritingPipe(address);

  // --- ИНИЦИАЛИЗАЦИЯ КРИПТО (актуальная) ---
  //(Изменено) Обязательный вызов begin() для Modern API
  aes.begin(); 
  aes.setKey(key, 16);
}

void loop() {
  char keyPress = keypad.waitForKey();
  byte plainBlock[16];
  byte cipherBlock[16];

  if (keyPress == '*') {
    armedFlag = false;
    digitalWrite(15, LOW);
    digitalWrite(17, LOW);
    delay(100);

    // --- ПОДГОТОВКА ДАННЫХ ---
    memset(plainBlock, 0, 16);
    plainBlock[0] = crypt_key;
    plainBlock[1] = check;
    packTimestamp(&plainBlock[2], millis());

    // --- ШИФРОВАНИЕ (актуальное) ---
    //(Изменено) Вызов через вложенный класс .Cipher
    // encryptBlock(Куда_положить_результат, Что_зашифровать)
    aes.Cipher.encryptBlock(cipherBlock, plainBlock); 

    radio.write(cipherBlock, 16);

    if (radio.available()) {
      byte answer;
      radio.read(&answer, 1);
      if (answer == 1) {
        armedFlag = true;
        digitalWrite(15, HIGH); 
        digitalWrite(17, LOW);
        Serial.println("Status OK. SYSTEM ARMED.");
      } else {
        Serial.println("Status BAD");
        digitalWrite(17, HIGH);
      }
    } else {
      Serial.println("No answer");
      digitalWrite(17, HIGH);
    }
  }

  else if (keyPress == '#') {
    armedFlag = false;
    digitalWrite(17, HIGH); 
    digitalWrite(15, LOW);
  }

  else if (keyPress >= '0' && keyPress <= '9' && armedFlag) {
    digitalWrite(17, HIGH);
    digitalWrite(15, LOW);

    int keyInt = keyPress - '0';
    memset(plainBlock, 0, 16);
    plainBlock[0] = crypt_key;
    plainBlock[1] = keyInt;
    packTimestamp(&plainBlock[2], millis());

    aes.Cipher.encryptBlock(cipherBlock, plainBlock); 

    radio.write(cipherBlock, 16);
    delay(10);

    digitalWrite(17, LOW);
    digitalWrite(15, HIGH);
    Serial.print("Fuse command sent: "); 
    Serial.println(keyInt);
  }
}
